findings.codeql_raw_query:
/**
 * @name Recon: file/subprocess/network operations and parse sinks
 * @description Enumerates functions in the package that call network or process functions
 * @kind problem
 * @problem.severity note
 * @id py/recon-io
 */
import python
import semmle.python.ApiGraphs

from DataFlow::CallCfgNode call, string what
where
  (
    call = API::moduleImport("urllib").getMember("urlopen").getACall() and what = "urllib.urlopen"
  ) or (
    call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() and what = "urllib.request.urlopen"
  ) or (
    call = API::moduleImport("urllib2").getMember("urlopen").getACall() and what = "urllib2.urlopen"
  ) or (
    call = API::moduleImport("os").getMember(["system", "popen", "spawn", "execv", "execvp"]).getACall() and what = "os exec"
  ) or (
    call = API::moduleImport("subprocess").getMember(["call", "Popen", "check_call", "check_output", "run"]).getACall() and what = "subprocess"
  ) or (
    call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and what = "pickle"
  ) or (
    call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and what = "marshal"
  ) or (
    call = API::moduleImport("tempfile").getMember(["mktemp", "mkstemp", "NamedTemporaryFile"]).getACall() and what = "tempfile"
  )
select call, what
